INSERT INTO diseases (disease_name, recommendation) VALUES
('Apple Scab Leaf', 'Удалите и сожгите пораженные листья и плоды. Обрабатывайте медьсодержащими фунгицидами до и после цветения. Осенью уничтожьте растительные остатки. Проводите прореживающую обрезку для вентиляции. Выбирайте устойчивые сорта.'),
('Apple leaf', 'Полностью здоровый лист яблони.'),
('Apple rust leaf', 'Удалите листья с оранжевыми пятнами. Не сажайте рядом с можжевельником. Обработайте медьсодержащими фунгицидами после цветения. Осенью перекопайте приствольный круг. Весной используйте бордосскую жидкость.'),
('Bell_pepper leaf spot', 'Удалите больные листья, обеспечьте вентиляцию. Поливайте только под корень. Обработайте «Фитоспорином» или медьсодержащими препаратами. Мульчируйте почву. Соблюдайте севооборот.'),
('Bell_pepper leaf', 'Полностью здоровый лист болгарского перца.'),
('Blueberry leaf', 'Полностью здоровый лист голубики.'),
('Cherry leaf', 'Полностью здоровый лист вишни.'),
('Corn Gray leaf spot', 'Соблюдайте севооборот. Используйте устойчивые гибриды. Уничтожайте послеуборочные остатки. Применяйте фунгициды при вспышке. Избегайте густых посевов.'),
('Corn leaf blight', 'Уничтожьте зараженные остатки после урожая. Выбирайте устойчивые гибриды. Обеспечьте пространство для проветривания. Обработайте фунгицидом при первых признаках. Сбалансируйте подкормки.'),
('Corn rust leaf', 'Обработайте фунгицидом при первых признаках. Удалите сильно пораженные растения. Поливайте под корень. Увеличьте калийные подкормки. Используйте устойчивые гибриды.'),
('Peach leaf', 'Полностью здоровый лист персика.'),
('Potato leaf early blight', 'Опрыскайте ботву медьсодержащими фунгицидами. Увеличьте калийные удобрения. Регулярно окучивайте. Уничтожайте ботву перед уборкой. Соблюдайте севооборот.'),
('Potato leaf late blight', 'Немедленно обработайте фунгицидами против фитофторы. Повторите обработку. Скосите ботву перед уборкой. Просушите клубни. Используйте здоровый посадочный материал.'),
('Potato leaf', 'Полностью здоровый лист картофеля.'),
('Raspberry leaf', 'Полностью здоровый лист малины.'),
('Soyabean leaf', 'Полностью здоровый лист сои.'),
('Soybean leaf', 'Полностью здоровый лист сои.'),
('Squash Powdery mildew leaf', 'Обработайте «Фитоспорином» или коллоидной серой. Удалите сильно пораженные листья. Нормализуйте полив. Обеспечьте освещение и проветривание. Подкормите калием.'),
('Strawberry leaf', 'Полностью здоровый лист земляники садовой (клубники).'),
('Tomato Early blight leaf', 'Удалите нижние пораженные листья. Обработайте медьсодержащим фунгицидом. Мульчируйте почву. Проветривайте теплицу. Подкормите калиевой селитрой.'),
('Tomato Septoria leaf spot', 'Удалите листья с белыми пятнами. Обработайте бордосской смесью. Избегайте загущенных посадок. Поливайте под корень. Соблюдайте севооборот.'),
('Tomato leaf bacterial spot', 'Удалите сильно пораженные растения. Используйте медьсодержащие бактерициды. Дезинфицируйте инструмент. Избегайте верхнего полива. Используйте протравленные семена.'),
('Tomato leaf late blight', 'Обработайте фунгицидом против фитофторы. Повторите обработку. Удалите пасынки и нижние листья. Прекратите полив. Сильно пораженные растения сожгите.'),
('Tomato leaf mosaic virus', 'Больное растение выкопайте и сожгите. Боритесь с тлей. Дезинфицируйте инструмент. Не используйте семена от больных растений. Сажайте устойчивые гибриды.'),
('Tomato leaf yellow virus', 'Удалите растение с вирусом. Установите ловушки для белокрылки. Обрабатывайте инсектицидами. Используйте устойчивые сорта. Уничтожайте сорняки.'),
('Tomato leaf', 'Полностью здоровый лист томата.'),
('Tomato mold leaf', 'Удалите заплесневелые листья. Улучшите вентиляцию, сократите полив. Обработайте «Триходермином». Избегайте перепадов температур. Мульчируйте почву.'),
('Tomato two spotted spider mites leaf', 'Обработайте акарицидом с обеих сторон листьев. Обрежьте зараженные листья. Уничтожьте сорняки. Осенью продезинфицируйте теплицу серной шашкой.'),
('grape leaf black rot', 'Удалите пораженные листья и грозди. Обеспечьте проветриваемость куста. Обработайте фунгицидами на основе манкоцеба. Проведите искореняющую обработку осенью. Сожгите опавшие листья.'),
('grape leaf', 'Полностью здоровый лист винограда.');